<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * One employee's pay in a payroll run (spec §5.7). gross and net are generated by PostgreSQL;
 * a line changes only while its run is a draft (trigger). Written only by
 * App\Services\Hr\PayrollService.
 */
class PayrollLine extends Model
{
    /** The amounts a person may edit on a draft line. */
    public const EDITABLE = ['overtime_hours', 'overtime_pay', 'bonus', 'unpaid_days', 'unpaid_deduction', 'social_insurance_employee',
        'housing_fund_employee', 'income_tax', 'other_deductions', 'social_insurance_employer', 'housing_fund_employer'];

    protected $guarded = ['id', 'gross', 'net'];

    public function run(): BelongsTo
    {
        return $this->belongsTo(PayrollRun::class, 'payroll_run_id');
    }

    public function employee(): BelongsTo
    {
        return $this->belongsTo(Employee::class);
    }

    /** The employer's share of social insurance and housing fund. */
    public function employerContributions(): string
    {
        return bcadd((string) $this->social_insurance_employer, (string) $this->housing_fund_employer, 4);
    }
}
